#![cfg(feature="player")]
#[path="support/audio_transitions.rs"]mod transitions;
#[path="support/rational_audio_seek.rs"]mod rational;
use fvid::{audio::AudioStream,playback_flac::FlacAudioReader};
use std::{io::Cursor,time::Duration,sync::{Arc,Mutex}};
use rational::{Packet,collect,exact,suffix,anchor};
fn root()->std::path::PathBuf{std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/playback-errors/flac-sample-seek")}
fn bytes(n:&str)->Vec<u8>{std::fs::read(root().join(n)).unwrap()}
fn cases()->Vec<serde_json::Value>{serde_json::from_slice::<serde_json::Value>(&bytes("manifest.json")).unwrap()["cases"].as_array().unwrap().clone()}
fn open(c:&serde_json::Value)->FlacAudioReader{FlacAudioReader::open(Cursor::new(bytes(c["file"].as_str().unwrap())),Default::default()).unwrap()}
fn oracle(c:&serde_json::Value)->Vec<Packet>{vec![Packet{rate:c["rate"].as_u64().unwrap()as u32,channels:c["channels"].as_u64().unwrap()as u16,num:0,den:1,data:bytes(c["oracle"].as_str().unwrap())}]}
fn end(c:&serde_json::Value)->(u128,u128){(4099,c["rate"].as_u64().unwrap()as u128)}
#[test]fn independent_pcm_raw_packet_seek_and_video_controls(){for c in cases(){let mut r=open(&c);assert!(r.flac().packets()>1);exact(&collect(&mut r),&oracle(&c),c["file"].as_str().unwrap());assert_eq!(r.seek_to(1),0);exact(&collect(&mut r),&oracle(&c),"raw packet seek remains packet-aligned");assert_eq!(r.seek_to(i64::MAX),4099);assert!(r.next_packet().unwrap().is_none());r.rewind();exact(&collect(&mut r),&oracle(&c),"rewind");}let mut v=fvid::playback_native::NativeReader::software(Cursor::new(bytes("neutral-video.mp4")),32<<20).unwrap();for _ in 0..6{assert_eq!(v.read_frame_raw().unwrap().unwrap().into_rgb(32<<20).unwrap(),vec![130;16*16*3]);}assert!(v.read_frame_raw().unwrap().is_none());}
#[test]fn duration_seek_starts_at_the_first_native_sample_at_or_after_request(){for c in cases(){let mut r=open(&c);let wanted=oracle(&c);let mut queries:Vec<_>=c["queries_ns"].as_array().unwrap().iter().map(|n|Duration::from_nanos(n.as_u64().unwrap())).collect();queries.push(Duration::MAX);for target in queries{let expected=suffix(&wanted,target,end(&c));let at=r.seek_time(target);assert_eq!(r.time_of(at),anchor(&expected,end(&c)),"{}:{target:?}:anchor",c["file"].as_str().unwrap());exact(&collect(&mut r),&expected,&format!("{}:{target:?}",c["file"].as_str().unwrap()));}r.seek_time(Duration::from_millis(1));assert_eq!(r.seek_to(1),0);exact(&collect(&mut r),&wanted,"raw seek clears precise floor");r.seek_time(Duration::from_millis(1));r.rewind();exact(&collect(&mut r),&wanted,"rewind clears precise floor");}}
#[test]fn actual_flac_worker_preserves_precise_pcm_stamps_and_flush_anchor(){use fvid::audio_thread::AudioPlayback;use transitions::{Capture,Trace,ended};for c in cases(){for target in [Duration::from_nanos(1),Duration::from_nanos(1000001),Duration::from_millis(27),rational::duration(end(&c).0,end(&c).1),Duration::MAX]{let expected=suffix(&oracle(&c),target,end(&c));let raw=Arc::new(Mutex::new(rational::RawTrace::default()));let capture=raw.clone();let trace=Arc::new(Mutex::new(Trace::default()));let mut worker=AudioPlayback::start(Box::new(open(&c)),move||Box::new(rational::RawCapture{inner:Capture::new(trace),raw:capture}));worker.seek(target);worker.play();ended(&worker,worker.generation());let got=raw.lock().unwrap();exact(&got.packets,&expected,c["file"].as_str().unwrap());assert_eq!(got.anchors,vec![anchor(&expected,end(&c))]);}}}
#[test]fn file_and_packet_count_admission_stay_strict(){for c in cases(){let data=bytes(c["file"].as_str().unwrap());let mut limits=fvid::playback_flac::Limits::default();limits.file_bytes=data.len()-1;let error=FlacAudioReader::open(data.as_slice(),limits).err().expect("file limit");assert!(error.to_string().contains("FLAC file byte limit exceeded"),"{error}");let mut limits=fvid::playback_flac::Limits::default();limits.packets=1;assert!(FlacAudioReader::open(data.as_slice(),limits).is_err());}}
